import random
from fractions import Fraction

def run_trial(seed: int) -> dict:
    random.seed(seed)

    def gaussian_elimination(A):
        m, n = len(A), len(A[0])
        for i in range(m):
            max_row = i
            for j in range(i+1, m):
                if abs(A[j][i]) > abs(A[max_row][i]):
                    max_row = j
            A[i], A[max_row] = A[max_row], A[i]
            for j in range(i+1, m):
                factor = Fraction(A[j][i], A[i][i])
                for k in range(n):
                    A[j][k] -= factor * A[i][k]
        return A

    def matrix_multiplication(A, B):
        m, n, p = len(A), len(B), len(B[0])
        C = [[0]*p for _ in range(m)]
        for i in range(m):
            for j in range(p):
                for k in range(n):
                    C[i][j] += A[i][k] * B[k][j]
        return C

    def twisted_quandle_action(phi, q):
        n = len(phi)
        quandle = [[0]*n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if phi[i][j]:
                    quandle[i][j] = (i + j) % q
                else:
                    quandle[i][j] = (q - 1 - (i + j)) % q
        return quandle

    def resolution_width(phi):
        n = len(phi)
        clauses = phi[:]
        stack = []
        while clauses:
            clause = random.choice(clauses)
            if not any(lit in stack for lit in clause):
                stack.append(random.choice(clause))
            else:
                literals = [lit for lit in clause if lit not in stack]
                if not literals:
                    return len(stack) + 1
                new_clause = []
                for lit in literals:
                    new_clause.extend([x for x in phi if x != -lit])
                clauses.remove(clause)
                clauses.extend(new_clause)
        return len(stack)

    def generate_boolean_formula(n):
        phi = [[random.choice([0, 1]) for _ in range(n)] for _ in range(n)]
        for i in range(n):
            phi[i][i] = 1
        return phi

